ALTER TABLE BILL ADD (PAID_AMOUNT NUMBER(19,4) DEFAULT 0 NOT NULL);
CREATE TABLE BILL_PAYMENT_ALLOCATION (ALLOCATION_ID VARCHAR2(36) PRIMARY KEY, BILL_ID VARCHAR2(36) NOT NULL, PAYMENT_ID VARCHAR2(36) NOT NULL, JOURNAL_NUMBER VARCHAR2(60) NOT NULL, AMOUNT NUMBER(19,4) NOT NULL, CURRENCY_CODE CHAR(3) NOT NULL, SETTLED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CREATED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT FK_BILL_ALLOCATION_BILL FOREIGN KEY (BILL_ID) REFERENCES BILL(BILL_ID), CONSTRAINT UQ_BILL_ALLOCATION_PAYMENT UNIQUE (PAYMENT_ID), CONSTRAINT CK_BILL_ALLOCATION_AMOUNT CHECK (AMOUNT > 0));
CREATE INDEX IX_BILL_ALLOCATION_BILL ON BILL_PAYMENT_ALLOCATION(BILL_ID);
